mapper.select:
select * from ( select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl_es on aaa.entrustStatus=sdl_es.ITEM_CODE and sdl_es.DICT_CODE='ENTRUST_STATUS' left join SYS_DATADICT_LIST sdl_pm on aaa.priceModel=sdl_pm.ITEM_CODE and sdl_pm.DICT_CODE='PRICE_MODEL' left join SYS_DATADICT_LIST sdl_ps on aaa.ps=sdl_ps.ITEM_CODE and sdl_ps.DICT_CODE='BACK_LEND_DIRECTION'
order by sdl_es.ORDER_NO, aaa.entrustId DESC)
order by ${sort} ${direction}

mapper.sql:
select T1.ENTRUST_ID entrustId, decode(T1.ENTRUST_STATUS,'08','流程中','有效') as effectiveStatusStr, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId,
T2.PORTFOLIO_NAME portfolioName, T7.TERM_TYPE termType, T7.TERM_DAYS repoTerm, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.PRICE_MODEL priceModel, T1.PRICE*100 price, T7.SETTLE_SPREED settleSpreed, T1.VDATE vdate, T1.MDATE mdate, NVL(T5.FINISH_AMT,0) finishAmt, round((NVL(T4.FINISH_AMT,0)+NVL(T5.ENT_FINISH_AMT,0))/(T1.ENTRUST_AMT),4)*100 execProcess, round(NVL(T5.FINISH_AMT,0)/(T1.ENTRUST_AMT),4)*100 transProcess, (NVL(T4.FINISH_AMT, 0)+ NVL(T5.ENT_FINISH_AMT, 0)) as execFinishAmt, (NVL(T1.ENTRUST_AMT,0) - NVL(T5.ENT_FINISH_AMT,0) - NVL(T4.FINISH_AMT,0)) as execRemainderAmt, NVL(T5.FINISH_AMT,0) as transFinishAmt, (NVL(T1.ENTRUST_AMT,0) - NVL(T5.FINISH_AMT,0)) as transRemainderAmt, T1.REMARK, null approver, TO_CHAR(T1.ENTRUST_DATE, 'yyyy-MM-dd') as entrustDateStr, T1.ENTRUST_DATE entrustDate, T1.COUNTER_ID counterId, mcp.COUNTER_NAME counterName from ETR_ENTRUST T1 left join MST_COUNTER_PARTY mcp on T1.COUNTER_ID=mcp.COUNTER_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId} INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT, SUM(ENT_FINISH_AMT) AS ENT_FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME where T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) and T1.TRADE_MARKET = #{TRADE_PLACE_01}

select T1.ENTRUST_ID entrustId, decode(T1.ENTRUST_STATUS,'08','流程中','有效') as effectiveStatusStr, T1.ENTRUST_STATUS entrustStatus, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID portfolioId,
T2.PORTFOLIO_NAME portfolioName, T7.TERM_TYPE termType, T7.TERM_DAYS repoTerm, T1.PS ps, T1.ENTRUST_AMT entrustAmt, T1.PRICE_MODEL priceModel, T1.PRICE*100 price, T7.SETTLE_SPREED settleSpreed, T1.VDATE vdate, T1.MDATE mdate, NVL(T5.FINISH_AMT,0) finishAmt, round((NVL(T4.FINISH_AMT,0)+NVL(T5.ENT_FINISH_AMT,0))/(T1.ENTRUST_AMT),4)*100 execProcess, round(NVL(T5.FINISH_AMT,0)/(T1.ENTRUST_AMT),4)*100 transProcess, (NVL(T4.FINISH_AMT, 0)+ NVL(T5.ENT_FINISH_AMT, 0)) as execFinishAmt, (NVL(T1.ENTRUST_AMT,0) - NVL(T5.ENT_FINISH_AMT,0) - NVL(T4.FINISH_AMT,0)) as execRemainderAmt, NVL(T5.FINISH_AMT,0) as transFinishAmt, (NVL(T1.ENTRUST_AMT,0) - NVL(T5.FINISH_AMT,0)) as transRemainderAmt, T1.REMARK, nextUser.userName as approver, TO_CHAR(T1.ENTRUST_DATE, 'yyyy-MM-dd') as entrustDateStr, T1.ENTRUST_DATE entrustDate, T1.COUNTER_ID counterId, mcp.COUNTER_NAME counterName from WFL_ETR_ENTRUST T1 left join MST_COUNTER_PARTY mcp on T1.COUNTER_ID=mcp.COUNTER_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T4 ON T1.ENTRUST_ID = T4.ENTRUST_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT, SUM(ENT_FINISH_AMT) AS ENT_FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID left join ( select nextApp.workFlowId, (select listagg(SYS_USER.REAL_NAME, ',') within group(order by SYS_USER.USER_NAME) from SYS_USER where instr(','||nextApp.nowUserId||',' , ','||SYS_USER.USER_NAME||',') > 0) userName from ( SELECT case when T.PROCESS_STATE = 'END' then null else T.NEXT_USER end AS nowUserId, sdpm.Workflow_Id as workFlowId FROM SYS_WFL_BUSINESS_LIST T inner join SYS_DATA_PROCESS_MARK sdpm on sdpm.business_data_pk1=T.TRADE_ID WHERE EXISTS (SELECT 1 FROM SYS_WFL_BUSINESS_LIST A WHERE A.SEQ_NO = (SELECT MAX(B.SEQ_NO) FROM SYS_WFL_BUSINESS_LIST B WHERE A.WORKFLOW_ID = B.WORKFLOW_ID) AND T.SEQ_NO = A.SEQ_NO) AND T.PROCESS_STATE in ('ING') and T.BUSINESS_TYPE='ETR53') nextApp ) nextUser on T1.Workflow_Id=nextUser.workFlowId LEFT JOIN WFL_ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME where T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N}) and T1.TRADE_MARKET = #{TRADE_PLACE_01}

if.where:
( aaa.entrustId || '|' || aaa.entrustStatus || '|' || aaa.invManagerId || '|' || aaa.portfolioId || '|'
                || '|T+' || aaa.settleSpreed || '|' || aaa.portfolioName || '|' || aaa.termType || '|' || aaa.ps || '|' || priceModel
                || '|' || aaa.settleSpreed || '|' || aaa.approver || '|' || aaa.REMARK
                || '|' || sdl_es.item_value || '|' || sdl_pm.item_value || '|' || sdl_ps.item_value || '|' || aaa.counterName
                like '%' || #{search} || '%'
                or to_char(aaa.entrustAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.entrustAmt)=#{search}
                or to_char(aaa.price,'FM99990.9990')=#{search} or  aaa.price||'' =#{search}
                or to_char(aaa.repoTerm)=#{search}
                or aaa.entrustDateStr=#{search}
                or aaa.entrustDateStr||'' =#{search}
                or aaa.entrustDateStr=#{year}||'-'||#{search}
                or replace(aaa.entrustDateStr,'-','/')=#{search}
                or replace(aaa.entrustDateStr,'-','/')=#{year}||'/'||#{search}
                or to_char(aaa.execProcess)=#{search}
                or to_char(aaa.transProcess)=#{search}
                )

mapper.select:
select * from ( select aaa.* from (SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.PORTFOLIO_NAME portfolioName, fpt.TYPE_11 finProdType, TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ round(NVL(TABLE01.pledgeAmount,0)/10000,2) pledgeAmount,/*已质押券面总额*/ round(NVL(TABLE01.pledStrdPrinAmt,0)/10000,2) pledStrdPrinAmt,/*可质押券面总额*/ case when MST_BOND_VALUATION_INFO.NETPRICE>nvl(prinAmt.prinAmt,100) then round(100/100,4)*100 when MST_BOND_VALUATION_INFO.NETPRICE is null then round(nvl(prinAmt.prinAmt,100)/100,4)*100 else round(MST_BOND_VALUATION_INFO.NETPRICE/nvl(prinAmt.prinAmt,100),4)*100 end as scale, /*折算比例*/ ETR_ENTRUST_PLEDGE.PLEDGE_STOCK_ID pledgeStockId,/*质押库代码*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ to_char(FIN_PRODUCT.MDATE,'yyyy-MM-dd') mdateStr, MBCR.GRADE_RESULT gradeResult,/*债项评级*/ FIN_PRODUCT.REGIST_ORG registOrg,/*登记托管机构*/ FIN_PRODUCT.FINPROD_ABBR finprodAbbr,/*金融产品名称*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ MST_BOND_VALUATION_INFO.NETPRICE firstNetPrice, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*市场代码*/ STL_SEC_ACCT_INFO.SEC_ACCT_NAME secAcctIdStr , ETR_SEC_STOCK.PLEDGE_STOCK_NAME PLEDGESTOCKNAME, case when atd.EX_PENDING_PERIOD IS NULL THEN atd.M_PENDING_PERIOD || atd.M_PENDING_PERIOD_UNIT else atd.EX_PENDING_PERIOD || atd.EX_PENDING_PERIOD_UNIT ||'+'|| atd.M_PENDING_PERIOD || atd.M_PENDING_PERIOD_UNIT end AS waitPeriod FROM ETR_ENTRUST_PLEDGE
LEFT JOIN PTL_PORTFOLIO_AUTHORITY PPA ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = PPA.PORTFOLIO_ID
left join ETR_SEC_STOCK on ETR_SEC_STOCK.PLEDGE_STOCK_ID=ETR_ENTRUST_PLEDGE.PLEDGE_STOCK_ID LEFT JOIN ( SELECT TEMP.PORTFOLIO_ID, /*组合代码*/ TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, /*证券账户/通道代码*/ TEMP.FINPROD_ID, /*组合起息日*/ TEMP.VDATE, /*分支序号*/ SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt, /*可质押券面总额*/ SUM(TEMP.pledgeAmount) pledgeAmount /*已质押质押券面总额*/ FROM ( SELECT espr.PORTFOLIO_ID, pp.PORTFOLIO_NAME, espr.SEC_ACCT_ID, espr.FINPROD_ID, pp.VDATE, CASE WHEN ppc.S_HOLDINGTYPE = #{S_002} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt, /*可质押券面总额*/ CASE WHEN espr.HODING_TYPE=#{A_012} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount /*已质押质押券面总额*/ FROM ETR_SEC_POSITION_RULE espr INNER JOIN PTL_PORTFOLIO pp ON espr.PORTFOLIO_ID = pp.PORTFOLIO_ID left JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE =#{S_002} WHERE 1 = 1 AND espr.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND espr.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE =#{S_002} or espr.HODING_TYPE=#{A_012}) ) TEMP
LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON TEMP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
WHERE 1 = 1 AND TEMP.VDATE <= to_date(#{sysDate},'yyyy-MM-dd') AND TEMP.PORTFOLIO_ID NOT IN (SELECT DISTINCT TFP.PORTFOLIO_ID PORTFOLIO_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL TFP WHERE (TFP.PS = 'C5' OR TFP.PS = 'C20') AND (TFP.IS_CANCEL !='Y' OR TFP.IS_CANCEL IS NULL) )
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
GROUP BY TEMP.PORTFOLIO_ID, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.VDATE HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ ON ETR_ENTRUST_PLEDGE.PORTFOLIO_ID = TABLE01.PORTFOLIO_ID AND ETR_ENTRUST_PLEDGE.FINPROD_ID = TABLE01.FINPROD_ID AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID = TABLE01.SEC_ACCT_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} AND FIN_PRODUCT.CCY = 'CNY' LEFT JOIN MST_BOND_MARKET_INFO mbmi ON FIN_PRODUCT.FINPROD_MARKET_ID = mbmi.SEC_ID AND mbmi.VALUE_DATE = to_date(#{sysDate},'yyyy-MM-dd') INNER JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = FIN_PRODUCT.FINPROD_ID left join ( select 100-sum(nvl(PRIN_AMT,0)) prinAmt,FINPROD_ID from FIN_CASH_PLAN WHERE MDATE <= to_date(#{sysDate},'yyyy-mm-dd') group by FINPROD_ID) prinAmt on prinAmt.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO on TABLE01.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD,T2.NETPRICE FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{sysDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = #{VALUATION_SOURCE_CBC} GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID /*以上获取债券小于等于平台日的最新估值行情*/ LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') and GRADE_ORG_ID !='22') MBCR ON MBCR.O_CODE = FIN_PRODUCT.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN ASSET_DAILY_INFO atd ON ETR_ENTRUST_PLEDGE.FINPROD_ID = atd.FINPROD_ID AND atd.CDATE = to_date(#{sysDate},'yyyy-MM-dd') WHERE 1=1 /*只获取交易场所为：01银行间*/ AND FIN_PRODUCT.TRADE_MARKET = #{TRADEPLACE01} AND FIN_PRODUCT.VDATE <= to_date(#{sysDate},'yyyy-MM-dd') AND FIN_PRODUCT.MDATE >= to_date(#{sysDate},'yyyy-MM-dd') AND (mbmi.MARKET_AMT > 0 OR mbmi.MARKET_AMT IS NULL )
AND PPA.USER_ID = #{loginUserId}
AND ETR_ENTRUST_PLEDGE.PORTFOLIO_ID in
#{item}
AND ETR_ENTRUST_PLEDGE.SEC_ACCT_ID in
#{item}
AND ETR_ENTRUST_PLEDGE.PLEDGE_STOCK_ID =#{zyqk}
AND FIN_PRODUCT.REGIST_ORG in
#{item}
AND FIN_PRODUCT.FINPROD_MARKET_ID in
#{item}
FIN_PRODUCT.REGIST_ORG = #{registOrg}
fpt.TYPE_11 = #{finProdType}
AND to_char(atd.EX_PENDING_PERIOD) = #{exPendingPeriod}
AND atd.EX_PENDING_PERIOD_UNIT = #{exPendingPeriodUnit}
AND to_char(atd.M_PENDING_PERIOD) = #{mPendingPeriod}
AND atd.M_PENDING_PERIOD_UNIT = #{mPendingPeriodUnit}
AND fpt.TYPE_11 in
#{item}
) aaa left join SYS_DATADICT_LIST sdl_es on aaa.gradeResult=sdl_es.ITEM_CODE and sdl_es.DICT_CODE='MAIN_GRADE_RESULT' left join SYS_DATADICT_LIST sdl_pm on aaa.registOrg=sdl_pm.ITEM_CODE and sdl_pm.DICT_CODE='REGIST_ORG' left join SYS_DATADICT_LIST sdl_ps on aaa.finProdType=sdl_ps.ITEM_CODE and sdl_ps.DICT_CODE='CUSTOM_ASSET_TYPE_FOUR'
(aaa.portfolioId || '|' || aaa.finprodAbbr || '|' || aaa.portfolioName || '|' || aaa.secAcctIdStr || '|' || sdl_ps.ITEM_VALUE || '|' || finProdId || '|' || sdl_es.ITEM_VALUE || '|' || aaa.PLEDGESTOCKNAME || '|' || sdl_pm.ITEM_VALUE || '|' || aaa.waitPeriod like '%' || #{search} || '%' or to_char(aaa.pledStrdPrinAmt)=#{search} or to_char(aaa.pledgeAmount)=#{search} or to_char(aaa.firstNetPrice)=#{search} or to_char(aaa.pledStrdPrinAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.pledStrdPrinAmt)=#{search} or to_char(aaa.pledgeAmount,'FM9999999999999990.90')=#{search} or aaa.pledgeAmount||'' =#{search} or to_char(aaa.firstNetPrice,'FM9999999999999990.9990')=#{search} or to_char(aaa.firstNetPrice)=#{search} or to_char(aaa.scale,'FM9999999999999990.90')=#{search} or aaa.scale||'' =#{search} or aaa.mdateStr=#{search} or aaa.mdateStr||'' =#{search} or aaa.mdateStr=#{year}||'-'||#{search} or replace(aaa.mdateStr,'-','/')=#{search} or replace(aaa.mdateStr,'-','/')=#{year}||'/'||#{search} )
)
order by ${sort} ${direction}

select tb.id id, tb.text text from( SELECT DISTINCT A.ACCT_NO id, B.SEC_ACCT_NAME text FROM PTL_SEC_ACCT A INNER JOIN STL_SEC_ACCT_INFO B ON A.ACCT_NO = B.SEC_ACCT_ID LEFT JOIN (SELECT sum(AMOUNT),PORTFOLIO_ID,SEC_ACCT_ID,FINPROD_ID FROM ETR_SEC_POSITION_RULE espr LEFT JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE = ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE = #{S_002} WHERE espr.DATE_TYPE =0 AND espr.CDATE =to_date(#{sysDate},'yyyy-MM-dd') GROUP BY PORTFOLIO_ID,SEC_ACCT_ID,FINPROD_ID HAVING sum(AMOUNT)>0) espr on A.PORTFOLIO_ID=espr.PORTFOLIO_ID and A.ACCT_NO=espr.SEC_ACCT_ID
AND ( A.ACCT_NO LIKE CONCAT('%', CONCAT(#{search}, '%')) OR B.SEC_ACCT_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND espr.PORTFOLIO_ID in
#{item}
)tb

select count(1)
	from ETR_SEC_STOCK
where PLEDGE_STOCK_NAME = #{pledgeStockName}

	 and  PLEDGE_STOCK_ID <> #{seqno}

select count(1)
	from ETR_SEC_STOCK_CONFIG
where PLEDGE_STOCK_ID = #{pledgeStockId}

        SELECT distinct
	        grp.PORTFOLIO_ID portfolioId,
	        grp.PORTFOLIO_NAME portfolioName
      FROM ptl_Portfolio grp
      LEFT JOIN PA_PTL_PORTFOLIO T2
		ON
		grp.PORTFOLIO_ID = T2.PORTFOLIO_ID

           left join PTL_SEC_STOCK psc on psc.PORTFOLIO_ID = grp.PORTFOLIO_ID

        where 1=1 and grp.PORTFOLIO_TYPE in ('01','03')

            AND grp.portfolio_id in

                #{item}



           and psc.PLEDGE_STOCK_ID = #{pledgeStockId}


            and grp.PROFIT_TYPE  in

                #{item}



            and T2.OPEN_TYPE in

                #{item}



            and T2.RAISE_TYPE in

                #{item}



            and T2.INVEST_NATURE in

                #{item}


			AND grp.PORTFOLIO_ID    IN
			  (SELECT PORTFOLIO_ID FROM PTL_PORTFOLIO_AUTHORITY WHERE USER_ID = #{username}
			  )

mapper.delete:
delete from ETR_ENTRUST_PLEDGE
where PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
  and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
  and BRANCH = #{branch,jdbcType=DECIMAL}
  and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
  and PLEDGE_STOCK_ID = #{pledgeStockId,jdbcType=VARCHAR}

mapper.select:
SELECT T.ACCT_NO FROM PTL_CAPACCT_INFO T 
	WHERE T.ACCT_TYPE ='A01' 
		AND T.PORTFOLIO_ID=#{portfolioId,jdbcType=VARCHAR}

SELECT TABLE01.PORTFOLIO_ID portfolioId,/*组合代码*/ TABLE01.SEC_ACCT_ID secAcctId,/*证券账户/通道代码*/ TABLE01.FINPROD_ID finProdId,/*金融产品Id*/ FIN_PRODUCT.FINPROD_ABBR finProdAbbr,/*金融产品简称*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*金融产品市场代码*/ TABLE01.BRANCH branch,/*分支序号*/ NVL(TABLE01.pledStrdPrinAmt,0) * 100 pledStrdPrinAmt,/*可质押券面总额*/ NVL(TABLE01.pledgeAmount,0) * 100 pledgeAmount,/*持仓券面总额*/ FIN_PRODUCT.TRADE_MARKET tradePlace,/*交易场所*/ FIN_PRODUCT.MDATE mdate,/*到期日*/ MST_BOND_VALUATION_INFO.LAST_PERIOD lastPeriod,/*剩余期限*/ MBCR.GRADE_RESULT gradeResult,/*债项评级*/ FIN_PRODUCT.REGIST_ORG registOrg,/*登记托管机构*/ NVL(fscr.SCALE, 1)*100 scale, /*折算比例*/ FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,/*市场代码*/ FIN_PRODUCT.ISSUER issuer, /*发行人*/ CASE WHEN FIN_PRODUCT2.IS_CHL = 'Y' THEN FIN_PRODUCT2.FINPROD_NAME ELSE STL_SEC_ACCT_INFO.SEC_ACCT_NAME END AS secAcctStr FROM ( SELECT TEMP.PORTFOLIO_ID, /*组合代码*/ TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, 0 branch, /*证券账户/通道代码*/ TEMP.FINPROD_ID, /*分支序号*/ SUM(TEMP.pledStrdPrinAmt) pledStrdPrinAmt, /*可质押券面总额*/ SUM(TEMP.pledgeAmount) pledgeAmount /*已质押质押券面总额*/ FROM ( SELECT espr.PORTFOLIO_ID, pp.PORTFOLIO_NAME, espr.SEC_ACCT_ID, espr.FINPROD_ID, CASE WHEN ppc.S_HOLDINGTYPE = #{S_002} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledStrdPrinAmt, /*可质押券面总额*/ CASE WHEN espr.HODING_TYPE=#{A_012} THEN espr.AMOUNT*nvl(ppc.CAL_FLAG,1) ELSE 0 END AS pledgeAmount /*已质押质押券面总额*/ FROM ETR_SEC_POSITION_RULE espr INNER JOIN PTL_PORTFOLIO pp ON espr.PORTFOLIO_ID = pp.PORTFOLIO_ID left JOIN PTL_POSITION_CFG ppc ON espr.HODING_TYPE =ppc.HOLDINGTYPE AND ppc.S_HOLDINGTYPE =#{S_002} WHERE 1 = 1 AND espr.CDATE = to_date(#{sysDate},'yyyy-MM-dd')/*组合持仓.日期 = 平台日*/ AND espr.DATE_TYPE =0 AND ( ppc.S_HOLDINGTYPE =#{S_002} or espr.HODING_TYPE=#{A_012}) ) TEMP
LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON TEMP.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID WHERE 1 = 1 AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
GROUP BY TEMP.PORTFOLIO_ID, TEMP.PORTFOLIO_NAME, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID HAVING SUM(TEMP.pledStrdPrinAmt) > 0 /*只统计可质押券面总额>0*/ )TABLE01/*以上统计可用持仓*/ LEFT JOIN STL_SEC_ACCT_INFO on TABLE01.SEC_ACCT_ID = STL_SEC_ACCT_INFO.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 on TABLE01.SEC_ACCT_ID = FIN_PRODUCT2.FINPROD_ID INNER JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TABLE01.FINPROD_ID LEFT JOIN ( SELECT T2.SEC_ID, T2.LAST_PERIOD FROM ( SELECT tmp1.SEC_ID, tmp1.value_source, MAX(tmp1.value_date) AS value_date FROM MST_BOND_VALUATION_INFO tmp1 LEFT JOIN FIN_PRODUCT tmp2 ON tmp1.sec_id = tmp2.finprod_market_id WHERE 1 = 1 AND tmp1.value_date <= to_date(#{sysDate},'yyyy-MM-dd')/*估值行情.日期 小于等于 平台日*/ AND tmp1.value_source = #{VALUATION_SOURCE_CBC} GROUP BY tmp1.sec_id, tmp1.value_source ) T1 LEFT JOIN MST_BOND_VALUATION_INFO T2 ON T1.SEC_ID = T2.SEC_ID AND T1.value_source = T2.value_source AND T1.VALUE_DATE = T2.VALUE_DATE ) MST_BOND_VALUATION_INFO/*以上获取债券小于等于平台日的最新估值行情*/ ON FIN_PRODUCT.FINPROD_MARKET_ID = MST_BOND_VALUATION_INFO.SEC_ID LEFT JOIN FIN_STDSEC_CONVERSE_RADIO fscr ON fscr.FINPROD_ID = TABLE01.FINPROD_ID AND fscr.BRANCH = TABLE01.BRANCH AND fscr.VDATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND NOT EXISTS ( SELECT * FROM FIN_STDSEC_CONVERSE_RADIO fscrInner WHERE fscrInner.FINPROD_ID = fscr.FINPROD_ID AND fscrInner.BRANCH = fscr.BRANCH AND fscrInner.VDATE <= to_date(#{sysDate}, 'yyyy-MM-dd') AND fscrInner.VDATE > fscr.VDATE ) LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC,CAST(GRADE_RESULT AS DECIMAL) DESC) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') and GRADE_ORG_ID !='22' ) MBCR ON MBCR.O_CODE = FIN_PRODUCT.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN FIN_PRODUCT_ADD FPA ON FIN_PRODUCT.FINPROD_ID = FPA.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = FIN_PRODUCT.FINPROD_ID WHERE 1=1 AND FIN_PRODUCT.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01} /*只获取交易场所为：01银行间，03上海证券交易所,04深圳证券交易所*/ AND FIN_PRODUCT.TRADE_MARKET = #{TRADEPLACE01}
AND (TABLE01.PORTFOLIO_ID in
null) or TABLE01.PORTFOLIO_ID in (
#{item}
)
AND T4.TYPE_9 = #{windtypeone,jdbcType=VARCHAR}
AND T4.TYPE_10 = #{windtypetwo,jdbcType=VARCHAR}
AND T4.TYPE_11 = #{windtypethree,jdbcType=VARCHAR}
AND FPA.IS_SEC_BOND = #{isSecBond,jdbcType=VARCHAR}
AND FIN_PRODUCT.IS_RIGHT = #{isRight,jdbcType=VARCHAR}
AND FPA.IS_PPB = #{isPpb,jdbcType=VARCHAR}

select distinct ess.pledge_stock_id id, ess.pledge_stock_name text, ess.IS_DEF_STOCK object from ETR_SEC_STOCK ess left join PTL_SEC_STOCK t on t.PLEDGE_STOCK_ID = ess.PLEDGE_STOCK_ID
and ess.pledge_stock_id = #{initValue, jdbcType=VARCHAR}
and ess.CREATE_USER = #{userId, jdbcType=VARCHAR}
and t.PORTFOLIO_ID in
#{item}
AND ( ess.pledge_stock_id LIKE CONCAT('%', CONCAT(#{search}, '%')) OR ess.pledge_stock_name LIKE CONCAT('%', CONCAT(#{search}, '%')) )
or t.PORTFOLIO_ID = #{portfolioId, jdbcType=VARCHAR}

select distinct t.pledge_stock_id id, t.pledge_stock_name text from ETR_SEC_STOCK t
CREATE_USER = #{userId}
ORDER BY CREATE_TIME DESC

select ess.PLEDGE_STOCK_ID, pss.PORTFOLIO_ID, essc.config_id, essc.pledge_stock_id, essc.windtypeone, essc.windtypetwo, essc.windtypethree, essc.m_grade_result, essc.sec_grade_result, essc.is_sec_bond, essc.is_right, essc.is_ppb, essc.create_user from ETR_SEC_STOCK ess left join ETR_SEC_STOCK_CONFIG essc on ess.PLEDGE_STOCK_ID = essc.PLEDGE_STOCK_ID left join PTL_SEC_STOCK pss on essc.PLEDGE_STOCK_ID = pss.PLEDGE_STOCK_ID where ess.CREATE_USER = #{userId} and (
pss.PORTFOLIO_ID in
#{item}
or pss.PORTFOLIO_ID is null
)
